import hashlib


class RecordProgram:
    """Recomputes the record's checkable result."""

    def __init__(self):
        self.figures = {"buildings": 5, "squares": 2, "streets": 3, "walks": 6}

    def run(self):
        total = sum(self.figures.values())
        return {"total": total,
                "digest": hashlib.sha256(str(total).encode()).hexdigest()}
